/**
 * sw.js — Stage 3's PWA infrastructure (spec §9.2). Hand-rolled, no
 * next-pwa/workbox — same "no new dependency" call as offline-db.ts, and
 * it keeps the exact caching strategy this file documents auditable in
 * one place rather than generated by a plugin.
 *
 * Plain JS, not TypeScript: this file ships as-is from public/, it is
 * never passed through Next's bundler. It therefore CANNOT `import` from
 * src/lib/offline-db.ts — the IndexedDB schema below (store names, key
 * shapes) is hand-duplicated from that file and MUST be kept in sync with
 * it by hand if either changes.
 *
 * Honest limitation carried from spec §9.2: a service worker only
 * registers on an https or localhost origin. Opening this app from a
 * plain `file://` path, or a non-localhost http origin, means none of
 * this activates — that is a browser restriction, not a bug here.
 */

const CACHE_VERSION = 'pbsms-v1'; // bump on every deploy that changes cached assets
const SHELL_CACHE = `${CACHE_VERSION}-shell`;
const DATA_CACHE = `${CACHE_VERSION}-data`;

// Precached at install. Next's hashed /_next/static/* bundle files are NOT
// enumerable without build-time integration (out of scope for a
// no-plugin, hand-rolled worker) — those are cached at runtime instead,
// the first time each one is actually requested (see the fetch handler).
const APP_SHELL_URLS = ['/manifest.json', '/icons/icon-192.png', '/icons/icon-512.png'];

// Spec §9.1's pre-fetch list — same GET endpoints the register/score
// screens call to build a roster or read current scores. Network-first
// with a cache fallback, refreshed on every successful connection, "never
// served stale-only." Only GETs ever reach this list (see the fetch
// handler's method check below) — a broad '/v1/assessment' prefix is safe
// even though POST .../scores is a mutation, because that POST never hits
// this handler at all.
const ROSTER_ENDPOINT_PREFIXES = [
  '/v1/classes',
  '/v1/academic-years',
  '/v1/students',
  '/v1/enrolments',
  '/v1/teacher-assignments',
  '/v1/assessment',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then((cache) => cache.addAll(APP_SHELL_URLS)).then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key.startsWith('pbsms-') && key !== SHELL_CACHE && key !== DATA_CACHE)
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

function isRosterRequest(url) {
  return ROSTER_ENDPOINT_PREFIXES.some((prefix) => url.pathname.startsWith(prefix));
}

function isStaticAsset(url) {
  return url.pathname.startsWith('/_next/static/') || url.pathname.startsWith('/icons/');
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  const url = new URL(req.url);

  // Only ever intercept same-origin GETs. Everything else (POST/PUT to the
  // API, cross-origin requests) passes straight through — nothing outside
  // attendance sync is offline-capable in v1 (spec §9.1).
  if (req.method !== 'GET' || url.origin !== self.location.origin) return;

  if (isStaticAsset(url)) {
    // Cache-first: a stale shell must never silently outlive a release,
    // which is why activate() above wipes any cache not matching the
    // current CACHE_VERSION — bumping that constant is what invalidates
    // this cache-first cache on deploy, not a runtime check here.
    event.respondWith(
      caches.match(req).then(
        (cached) =>
          cached ||
          fetch(req).then((res) => {
            const copy = res.clone();
            caches.open(SHELL_CACHE).then((cache) => cache.put(req, copy));
            return res;
          }),
      ),
    );
    return;
  }

  if (isRosterRequest(url)) {
    event.respondWith(
      fetch(req)
        .then((res) => {
          const copy = res.clone();
          caches.open(DATA_CACHE).then((cache) => cache.put(req, copy));
          return res;
        })
        .catch(() => caches.match(req).then((cached) => cached || Response.error())),
    );
    return;
  }

  if (req.mode === 'navigate') {
    // Network-first for the shell HTML itself, falling back to a
    // previously-visited page's cached response when offline.
    event.respondWith(fetch(req).catch(() => caches.match(req)));
  }
});

// ---------------------------------------------------------------------
// Background Sync (spec §9.2 "Service worker — queued writes") — flushes
// the IndexedDB queues offline-sync.ts wrote to. Attendance flushes as one
// idempotent batch (/v1/attendance/sync); scores flush one request per
// entry (Stage 4 — see offline-sync.ts's file header for why there's no
// batch/idempotent score-sync endpoint). This worker is a delivery
// mechanism for those two queues, not a third queue of its own.
// ---------------------------------------------------------------------

const DB_VERSION = 2; // bumped for Stage 4's pending_scores store — MUST match offline-db.ts's DB_VERSION
const STORE_QUEUE = 'pending_attendance';
const STORE_SCORE_QUEUE = 'pending_scores';
const STORE_AUTH = 'auth_mirror';
const DEFAULT_API_BASE_URL = 'http://localhost:3000'; // matches apps/web/src/lib/api-client.ts's own default

function openTenantDb(name) {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(name, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_QUEUE)) db.createObjectStore(STORE_QUEUE, { keyPath: 'clientId' });
      if (!db.objectStoreNames.contains(STORE_SCORE_QUEUE)) db.createObjectStore(STORE_SCORE_QUEUE, { keyPath: 'clientId' });
      if (!db.objectStoreNames.contains('roster_cache')) db.createObjectStore('roster_cache', { keyPath: 'key' });
      if (!db.objectStoreNames.contains(STORE_AUTH)) db.createObjectStore(STORE_AUTH, { keyPath: 'key' });
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function storeGetAll(db, storeName) {
  return new Promise((resolve, reject) => {
    const req = db.transaction(storeName, 'readonly').objectStore(storeName).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function storeGet(db, storeName, key) {
  return new Promise((resolve, reject) => {
    const req = db.transaction(storeName, 'readonly').objectStore(storeName).get(key);
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function storePutAll(db, storeName, rows) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, 'readwrite');
    const store = tx.objectStore(storeName);
    rows.forEach((row) => store.put(row));
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function storeDelete(db, storeName, key) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeName, 'readwrite');
    tx.objectStore(storeName).delete(key);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function postAttendanceBatch(apiBaseUrl, accessToken, entries) {
  const res = await fetch(`${apiBaseUrl}/v1/attendance/sync`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${accessToken}` },
    body: JSON.stringify({
      entries: entries.map((e) => ({
        clientId: e.clientId,
        studentId: e.studentId,
        classId: e.classId,
        attendanceDate: e.attendanceDate,
        session: e.session,
        status: e.status,
        deviceTimestamp: e.deviceTimestamp,
      })),
    }),
  });
  return res;
}

async function refreshAccessToken(apiBaseUrl, refreshToken) {
  const res = await fetch(`${apiBaseUrl}/v1/auth/refresh`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ refreshToken }),
  });
  if (!res.ok) return null;
  return res.json();
}

async function notifyClients(type, tenantId, lastSyncedAt) {
  const clients = await self.clients.matchAll();
  clients.forEach((client) => client.postMessage({ type, tenantId, lastSyncedAt }));
}

/** One tenant database's worth of queued attendance marks, flushed
 * through the real endpoint with one refresh-and-retry on a 401 — mirrors
 * apiFetch()'s own retry-once semantics in src/lib/api-client.ts, because
 * this worker has no access to that module either. */
async function flushTenantQueue(dbName) {
  const tenantId = dbName.replace('pbsms-offline-', '');
  const db = await openTenantDb(dbName);

  const authRow = await storeGet(db, STORE_AUTH, 'access');
  const refreshRow = await storeGet(db, STORE_AUTH, 'refresh');
  const apiBaseRow = await storeGet(db, STORE_AUTH, 'apiBaseUrl');
  const apiBaseUrl = apiBaseRow ? apiBaseRow.value : DEFAULT_API_BASE_URL;
  if (!authRow) return; // never logged in on this device/tenant — nothing to authenticate with

  const all = await storeGetAll(db, STORE_QUEUE);
  const toSend = all.filter((e) => e.syncState === 'pending' || e.syncState === 'failed');
  if (toSend.length === 0) return;

  let accessToken = authRow.value;
  let res = await postAttendanceBatch(apiBaseUrl, accessToken, toSend);

  if (res.status === 401 && refreshRow) {
    const refreshed = await refreshAccessToken(apiBaseUrl, refreshRow.value);
    if (refreshed) {
      accessToken = refreshed.accessToken;
      await storePutAll(db, STORE_AUTH, [
        { key: 'access', value: refreshed.accessToken },
        { key: 'refresh', value: refreshed.refreshToken },
      ]);
      res = await postAttendanceBatch(apiBaseUrl, accessToken, toSend);
    }
  }

  if (!res.ok) {
    // Still offline, or auth genuinely lapsed — leave everything queued
    // as-is (still 'pending'/'failed') for the next sync attempt or the
    // next time the page is open and can drive a manual retry.
    return;
  }

  const outcomes = await res.json();
  const updated = [];
  const toDelete = [];
  toSend.forEach((entry, i) => {
    const outcome = outcomes[i];
    if (!outcome) return;
    if (outcome.outcome === 'conflict') {
      updated.push({
        ...entry,
        syncState: 'failed',
        conflictId: outcome.conflictId,
        failReason: 'A different teacher already recorded a different status for this student — needs review.',
      });
    } else if (outcome.outcome === 'forbidden') {
      updated.push({ ...entry, syncState: 'failed', failReason: outcome.reason });
    } else {
      toDelete.push(entry.clientId); // sent — same prune-on-success rule offline-sync.ts uses
    }
  });
  if (updated.length > 0) await storePutAll(db, STORE_QUEUE, updated);
  for (const clientId of toDelete) await storeDelete(db, STORE_QUEUE, clientId);

  await notifyClients('pbsms-sync-update', tenantId, new Date().toISOString());
}

async function postScore(apiBaseUrl, accessToken, entry) {
  return fetch(`${apiBaseUrl}/v1/assessment/components/${entry.componentId}/scores`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${accessToken}` },
    body: JSON.stringify({
      studentId: entry.studentId,
      status: entry.status,
      value: entry.value,
      missingReason: entry.missingReason,
      expectedVersion: entry.expectedVersion,
    }),
  });
}

/**
 * One tenant database's worth of queued SCORE entries. Unlike attendance
 * there's no batch endpoint — each entry is its own request, and unlike
 * attendance a 401 refresh is attempted once per entry rather than once
 * for the whole flush (each request needs a valid token independently).
 * A 403/404/409 is a definitive server verdict, not a reason to keep
 * retrying — recorded as 'failed' with the server's own message, same as
 * offline-sync.ts's postScore() does on the page side.
 */
async function flushTenantScoreQueue(dbName) {
  const tenantId = dbName.replace('pbsms-offline-', '');
  const db = await openTenantDb(dbName);

  const authRow = await storeGet(db, STORE_AUTH, 'access');
  const refreshRow = await storeGet(db, STORE_AUTH, 'refresh');
  const apiBaseRow = await storeGet(db, STORE_AUTH, 'apiBaseUrl');
  const apiBaseUrl = apiBaseRow ? apiBaseRow.value : DEFAULT_API_BASE_URL;
  if (!authRow) return;

  const all = await storeGetAll(db, STORE_SCORE_QUEUE);
  const toSend = all.filter((e) => e.syncState === 'pending' || e.syncState === 'failed');
  if (toSend.length === 0) return;

  let accessToken = authRow.value;
  let anySent = false;

  for (const entry of toSend) {
    let res = await postScore(apiBaseUrl, accessToken, entry);

    if (res.status === 401 && refreshRow) {
      const refreshed = await refreshAccessToken(apiBaseUrl, refreshRow.value);
      if (refreshed) {
        accessToken = refreshed.accessToken;
        await storePutAll(db, STORE_AUTH, [
          { key: 'access', value: refreshed.accessToken },
          { key: 'refresh', value: refreshed.refreshToken },
        ]);
        res = await postScore(apiBaseUrl, accessToken, entry);
      }
    }

    if (res.ok) {
      await storeDelete(db, STORE_SCORE_QUEUE, entry.clientId);
      anySent = true;
    } else if (res.status === 403 || res.status === 404 || res.status === 409) {
      const body = await res.json().catch(() => null);
      const message = body && body.message;
      const failReason = Array.isArray(message) ? message.join('; ') : message || `Could not be saved (${res.status})`;
      await storePutAll(db, STORE_SCORE_QUEUE, [{ ...entry, syncState: 'failed', failReason }]);
    }
    // else (offline/5xx): leave this entry queued as-is for the next sync attempt
  }

  if (anySent) await notifyClients('pbsms-score-sync-update', tenantId, new Date().toISOString());
}

async function flushAllTenantQueues() {
  // indexedDB.databases() isn't in every browser's spec coverage, but is
  // supported on Chrome/Edge for Android — the spec's own stated Teacher
  // Field App target device (§ "Personal Android phone"). In practice a
  // device only ever has one tenant's DB at a time (cleared on logout,
  // see offline-db.ts's clearOfflineDb()), so this enumeration is a
  // correctness belt, not the common case.
  if (!indexedDB.databases) return;
  const dbs = await indexedDB.databases();
  const tenantDbs = dbs.filter((d) => d.name && d.name.startsWith('pbsms-offline-'));
  for (const d of tenantDbs) {
    await flushTenantQueue(d.name).catch(() => {
      // one tenant's failure must not block another's — Background Sync
      // will simply retry (the browser reschedules a failed sync event).
    });
    await flushTenantScoreQueue(d.name).catch(() => {});
  }
}

// Both tags trigger the same combined flush — each per-queue function
// early-returns on an empty queue, so this is a cheap no-op for whichever
// queue has nothing pending. Simpler and more robust than routing tags to
// separate handlers if a browser ever coalesces/reorders sync events.
self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-attendance' || event.tag === 'sync-scores') {
    event.waitUntil(flushAllTenantQueues());
  }
});
